-- Initial kailor relational schema. UUIDs are generated by Prisma.

CREATE TABLE "AdminUser" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "email" TEXT NOT NULL,
  "passwordHash" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE UNIQUE INDEX "AdminUser_email_key" ON "AdminUser"("email");

CREATE TABLE "AuthSession" (
  "tokenHash" TEXT NOT NULL PRIMARY KEY,
  "adminId" TEXT NOT NULL,
  "expiresAt" TIMESTAMP(3) NOT NULL
);

CREATE TABLE "Subject" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "name" TEXT NOT NULL,
  "synthetic" BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE "DiscoverySession" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "adminId" TEXT NOT NULL,
  "subjectId" TEXT NOT NULL,
  "definitionVersion" TEXT NOT NULL,
  "revision" INTEGER NOT NULL DEFAULT 0,
  "synthetic" BOOLEAN NOT NULL DEFAULT false,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL
);

CREATE TABLE "DiscoveryAnswer" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "sessionId" TEXT NOT NULL,
  "questionId" TEXT NOT NULL,
  "value" JSONB NOT NULL,
  "skipped" BOOLEAN NOT NULL DEFAULT false,
  "updatedAt" TIMESTAMP(3) NOT NULL
);

CREATE UNIQUE INDEX "DiscoveryAnswer_sessionId_questionId_key" ON "DiscoveryAnswer"("sessionId", "questionId");

CREATE TABLE "ConversationMessage" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "sessionId" TEXT NOT NULL,
  "role" TEXT NOT NULL,
  "content" TEXT NOT NULL,
  "provider" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "Evidence" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "sessionId" TEXT NOT NULL,
  "key" TEXT NOT NULL,
  "value" JSONB NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'inferred',
  "source" TEXT NOT NULL,
  "active" BOOLEAN NOT NULL DEFAULT true,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX "Evidence_sessionId_active_idx" ON "Evidence"("sessionId", "active");

CREATE TABLE "Assessment" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "sessionId" TEXT NOT NULL,
  "sessionRevision" INTEGER NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'draft',
  "summary" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE UNIQUE INDEX "Assessment_sessionId_sessionRevision_key" ON "Assessment"("sessionId", "sessionRevision");

CREATE TABLE "Service" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "name" TEXT NOT NULL,
  "delivery" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "hoursLow" INTEGER,
  "hoursHigh" INTEGER
);

CREATE TABLE "Recommendation" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "assessmentId" TEXT NOT NULL,
  "serviceId" TEXT NOT NULL,
  "problem" TEXT NOT NULL,
  "solution" TEXT NOT NULL,
  "evidence" JSONB NOT NULL,
  "benefits" JSONB NOT NULL,
  "alternatives" JSONB NOT NULL,
  "complexity" TEXT NOT NULL,
  "dependencies" JSONB NOT NULL,
  "confidence" TEXT NOT NULL,
  "delivery" TEXT NOT NULL,
  "nextSteps" JSONB NOT NULL,
  "optional" BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE "CostEstimate" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "recommendationId" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'manual_review',
  "currency" TEXT NOT NULL,
  "implementationLow" DOUBLE PRECISION,
  "implementationHigh" DOUBLE PRECISION,
  "recurringStatus" TEXT NOT NULL DEFAULT 'vendor_quote_required',
  "notes" TEXT NOT NULL
);

CREATE UNIQUE INDEX "CostEstimate_recommendationId_key" ON "CostEstimate"("recommendationId");

CREATE TABLE "ReportSnapshot" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "assessmentId" TEXT NOT NULL,
  "content" JSONB NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE UNIQUE INDEX "ReportSnapshot_assessmentId_key" ON "ReportSnapshot"("assessmentId");

CREATE TABLE "ScenarioTemplate" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "title" TEXT NOT NULL,
  "industry" TEXT NOT NULL,
  "definition" JSONB NOT NULL
);

CREATE TABLE "SimulationRun" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "personaId" TEXT NOT NULL,
  "persona" JSONB NOT NULL,
  "sessionId" TEXT NOT NULL,
  "discoveryPath" JSONB NOT NULL,
  "assessmentId" TEXT NOT NULL,
  "evaluationNotes" TEXT NOT NULL,
  "approvalStatus" TEXT NOT NULL DEFAULT 'pending',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "CaseIntelligenceRecord" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "sourceType" TEXT NOT NULL,
  "sourceRunId" TEXT,
  "reviewStatus" TEXT NOT NULL DEFAULT 'pending',
  "title" TEXT NOT NULL,
  "pattern" JSONB NOT NULL,
  "reviewNotes" TEXT,
  "reviewedAt" TIMESTAMP(3),
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "AiUsageRecord" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "sessionId" TEXT NOT NULL,
  "provider" TEXT NOT NULL,
  "mode" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  "reservedTokens" INTEGER NOT NULL,
  "reason" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX "AiUsageRecord_createdAt_provider_idx" ON "AiUsageRecord"("createdAt", "provider");

CREATE TABLE "AuditEvent" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "actorId" TEXT NOT NULL,
  "action" TEXT NOT NULL,
  "entityId" TEXT NOT NULL,
  "details" JSONB NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE "AuthSession" ADD CONSTRAINT "AuthSession_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "AdminUser"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "DiscoverySession" ADD CONSTRAINT "DiscoverySession_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "AdminUser"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "DiscoverySession" ADD CONSTRAINT "DiscoverySession_subjectId_fkey" FOREIGN KEY ("subjectId") REFERENCES "Subject"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "DiscoveryAnswer" ADD CONSTRAINT "DiscoveryAnswer_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "DiscoverySession"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "ConversationMessage" ADD CONSTRAINT "ConversationMessage_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "DiscoverySession"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "Evidence" ADD CONSTRAINT "Evidence_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "DiscoverySession"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "Assessment" ADD CONSTRAINT "Assessment_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "DiscoverySession"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "Recommendation" ADD CONSTRAINT "Recommendation_assessmentId_fkey" FOREIGN KEY ("assessmentId") REFERENCES "Assessment"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "Recommendation" ADD CONSTRAINT "Recommendation_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "Service"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "CostEstimate" ADD CONSTRAINT "CostEstimate_recommendationId_fkey" FOREIGN KEY ("recommendationId") REFERENCES "Recommendation"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "ReportSnapshot" ADD CONSTRAINT "ReportSnapshot_assessmentId_fkey" FOREIGN KEY ("assessmentId") REFERENCES "Assessment"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "SimulationRun" ADD CONSTRAINT "SimulationRun_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "DiscoverySession"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "CaseIntelligenceRecord" ADD CONSTRAINT "CaseIntelligenceRecord_sourceRunId_fkey" FOREIGN KEY ("sourceRunId") REFERENCES "SimulationRun"("id") ON DELETE SET NULL ON UPDATE CASCADE;

ALTER TABLE "AiUsageRecord" ADD CONSTRAINT "AiUsageRecord_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "DiscoverySession"("id") ON DELETE CASCADE ON UPDATE CASCADE;
